# situ capability map v1
# schema: keystore.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.

# codecs. `trusted` means the properties are declared and
# unverified: run `situc gen-codec-tests` to falsify a lying one.
codec aes_gcm_256 trusted length_preserving seekable=linear granularity=byte authenticated invertible deterministic

struct argon2_params size=9 repr=ValueConverted
  argon2_params.memory_kib               offset=AbsoluteStatic(0x00) size=Fixed(4) align=Aligned(8) repr=ValueConverted atomic=AtomicWord
  argon2_params.passes                   offset=AbsoluteStatic(0x04) size=Fixed(4) align=Aligned(4) repr=ValueConverted atomic=AtomicWord
  argon2_params.lanes                    offset=AbsoluteStatic(0x08) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord

struct keystore size=87 mutate=Immutable address=Unstable repr=ValueConverted atomic=NonAtomic stage=VerifyGated auth=Covered(tag) secrecy=Secret
  keystore.magic                         offset=AbsoluteStatic(0x00) size=Fixed(4) align=Aligned(8) repr=ValueConverted atomic=AtomicWord
  keystore.version                       offset=AbsoluteStatic(0x04) size=Fixed(1) align=Aligned(4) repr=MemoryIdentical atomic=AtomicWord
  keystore.salt                          offset=AbsoluteStatic(0x05) size=Fixed(16) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic
  keystore.nonce                         offset=AbsoluteStatic(0x15) size=Fixed(12) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic
  keystore.params                        offset=AbsoluteStatic(0x21) size=Bounded(4, 9) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting
  keystore.params.pbkdf2                 offset=AbsoluteStatic(0x21) size=Fixed(4) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  keystore.params.pbkdf2.iterations      offset=AbsoluteStatic(0x21) size=Fixed(4) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  keystore.params.argon2                 offset=AbsoluteStatic(0x21) size=Fixed(9) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  keystore.params.argon2.memory_kib      offset=AbsoluteStatic(0x21) size=Fixed(4) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  keystore.params.argon2.passes          offset=AbsoluteStatic(0x25) size=Fixed(4) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  keystore.params.argon2.lanes           offset=AbsoluteStatic(0x29) size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord
  keystore.length                        offset=Dynamic size=Fixed(2) align=Unaligned repr=ValueConverted atomic=NonAtomic address=Unstable
  keystore.sealed                        offset=Dynamic size=Bounded(32, 4096) align=Unaligned repr=MemoryIdentical atomic=NonAtomic mutate=Shifting address=Unstable stage=VerifyGated auth=Covered(tag)
  keystore.sealed.secret_key             offset=Dynamic size=Fixed(32) align=Unaligned repr=MemoryIdentical atomic=NonAtomic address=Unstable stage=VerifyGated auth=Covered(tag) secrecy=Secret
  keystore.sealed.plaintext              offset=Dynamic size=Bounded(0, 4064) align=Unaligned repr=MemoryIdentical atomic=AtomicWord mutate=Shifting address=Unstable stage=VerifyGated auth=Covered(tag)
  keystore.tag                           offset=Dynamic size=Fixed(16) align=Unaligned repr=MemoryIdentical atomic=NonAtomic mutate=Immutable address=Unstable

struct pbkdf2_params size=4 repr=ValueConverted
  pbkdf2_params.iterations               offset=AbsoluteStatic(0x00) size=Fixed(4) align=Aligned(8) repr=ValueConverted atomic=AtomicWord
